CREATE TABLE IF NOT EXISTS clients (id INT PRIMARY KEY AUTO_INCREMENT,name TEXT NOT NULL,rif VARCHAR(50) UNIQUE,address TEXT,phone VARCHAR(20),email VARCHAR(255),contact VARCHAR(100));
CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY AUTO_INCREMENT,name TEXT NOT NULL,barcode VARCHAR(255) UNIQUE,description TEXT,category VARCHAR(100),price DECIMAL(10,2) NOT NULL,unit VARCHAR(50),hasSerial BOOLEAN,stock INT);
CREATE TABLE IF NOT EXISTS company_config (id INT PRIMARY KEY AUTO_INCREMENT,businessName TEXT,rif VARCHAR(50),address TEXT,phone1 VARCHAR(20),phone2 VARCHAR(20),email VARCHAR(255),website VARCHAR(255),ivaRate DECIMAL(5,2));
CREATE TABLE IF NOT EXISTS delivery_notes (id INT PRIMARY KEY AUTO_INCREMENT,noteNumber VARCHAR(50) UNIQUE NOT NULL,noteDate DATE NOT NULL,clientName TEXT NOT NULL,clientRif VARCHAR(50),clientAddress TEXT,clientPhone VARCHAR(20),clientContact VARCHAR(100),subtotal DECIMAL(12,2),applyIVA BOOLEAN,ivaAmount DECIMAL(12,2),total DECIMAL(12,2),observations TEXT,deliveredBy VARCHAR(100),receivedBy VARCHAR(100));
CREATE TABLE IF NOT EXISTS note_lines (id INT PRIMARY KEY AUTO_INCREMENT,noteId INT NOT NULL,productId INT NOT NULL,quantity INT NOT NULL,unitPrice DECIMAL(10,2),lineTotal DECIMAL(12,2));
CREATE TABLE IF NOT EXISTS serials (id INT PRIMARY KEY AUTO_INCREMENT,lineId INT NOT NULL,serial VARCHAR(255) NOT NULL,UNIQUE(lineId,serial));
CREATE TABLE IF NOT EXISTS budgets (id INT PRIMARY KEY AUTO_INCREMENT,budgetNumber VARCHAR(50) UNIQUE NOT NULL,budgetDate DATE NOT NULL,clientName TEXT NOT NULL,clientRif VARCHAR(50),clientAddress TEXT,clientPhone VARCHAR(20),clientContact VARCHAR(100),subtotal DECIMAL(12,2),applyIVA BOOLEAN,ivaAmount DECIMAL(12,2),total DECIMAL(12,2),observations TEXT);
CREATE TABLE IF NOT EXISTS budget_lines (id INT PRIMARY KEY AUTO_INCREMENT,budgetId INT NOT NULL,productId INT,description TEXT NOT NULL,quantity INT NOT NULL,unitPrice DECIMAL(10,2),lineTotal DECIMAL(12,2));
